@prefix acttype: <https://w3id.org/ogc/rim/activity-type/> .
@prefix rim: <https://w3id.org/ogc/rim/> .
@prefix sh: <http://www.w3.org/ns/shacl#> .
@prefix xsd: <http://www.w3.org/2001/XMLSchema#> .

[] a sh:ValidationReport ;
    sh:conforms false ;
    sh:result [ a sh:ValidationResult ;
            sh:focusNode <file:///github/workspace/Buffer> ;
            sh:resultMessage "An activity type's rim:itemClass must be acttype:activityTypeItemClass." ;
            sh:resultPath rim:itemClass ;
            sh:resultSeverity sh:Violation ;
            sh:sourceConstraintComponent sh:HasValueConstraintComponent ;
            sh:sourceShape [ sh:hasValue acttype:activityTypeItemClass ;
                    sh:message "An activity type's rim:itemClass must be acttype:activityTypeItemClass." ;
                    sh:path rim:itemClass ] ] .

