@prefix rim: <https://w3id.org/ogc/rim/> .
@prefix sh: <http://www.w3.org/ns/shacl#> .
@prefix xsd: <http://www.w3.org/2001/XMLSchema#> .

[] a sh:ValidationReport ;
    sh:conforms false ;
    sh:result [ a sh:ValidationResult ;
            sh:focusNode <file:///github/workspace/Buffer> ;
            sh:resultMessage "Less than 1 values on <file:///github/workspace/Buffer>->rim:itemClass" ;
            sh:resultPath rim:itemClass ;
            sh:resultSeverity sh:Violation ;
            sh:sourceConstraintComponent sh:MinCountConstraintComponent ;
            sh:sourceShape [ sh:class rim:RegisterItemClass ;
                    sh:maxCount 1 ;
                    sh:minCount 1 ;
                    sh:path rim:itemClass ] ],
        [ a sh:ValidationResult ;
            sh:focusNode <file:///github/workspace/Buffer> ;
            sh:resultMessage "Less than 1 values on <file:///github/workspace/Buffer>->rim:objectIdentifier" ;
            sh:resultPath rim:objectIdentifier ;
            sh:resultSeverity sh:Violation ;
            sh:sourceConstraintComponent sh:MinCountConstraintComponent ;
            sh:sourceShape [ sh:datatype xsd:anyURI ;
                    sh:maxCount 1 ;
                    sh:minCount 1 ;
                    sh:path rim:objectIdentifier ] ],
        [ a sh:ValidationResult ;
            sh:focusNode <file:///github/workspace/Buffer> ;
            sh:resultMessage "Less than 1 values on <file:///github/workspace/Buffer>->rim:validityStatus" ;
            sh:resultPath rim:validityStatus ;
            sh:resultSeverity sh:Violation ;
            sh:sourceConstraintComponent sh:MinCountConstraintComponent ;
            sh:sourceShape [ sh:class rim:ValidityStatus ;
                    sh:maxCount 1 ;
                    sh:minCount 1 ;
                    sh:path rim:validityStatus ] ],
        [ a sh:ValidationResult ;
            sh:focusNode <file:///github/workspace/Buffer> ;
            sh:resultMessage "Less than 1 values on <file:///github/workspace/Buffer>->rim:publicationStatus" ;
            sh:resultPath rim:publicationStatus ;
            sh:resultSeverity sh:Violation ;
            sh:sourceConstraintComponent sh:MinCountConstraintComponent ;
            sh:sourceShape [ sh:class rim:PublicationStatus ;
                    sh:maxCount 1 ;
                    sh:minCount 1 ;
                    sh:path rim:publicationStatus ] ] .

